/**
 * @name Path traversal
 * @description Accessing files using user-controlled paths can lead to path traversal.
 * @kind path-problem
 * @problem.severity error
 * @id py/httpx/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Header Injection (CRLF)
 * @description User input in HTTP headers without validation can lead to CRLF injection.
 * @kind path-problem
 * @problem.severity error
 * @id py/httpx/crlf-injection
 * @tags security
 *       external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module CrlfInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Check for adding headers in httpx models or client
      call = API::moduleImport("httpx").getMember("Headers").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CrlfInjectionFlow = TaintTracking::Global<CrlfInjectionConfig>;
import CrlfInjectionFlow::PathGraph

from CrlfInjectionFlow::PathNode source, CrlfInjectionFlow::PathNode sink
where CrlfInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential CRLF injection in headers from $@.", source.getNode(), "user input"

/**
 * @name HTTP Header Injection
 * @description User input into HTTP headers can cause header injection or splitting.
 * @kind path-problem
 * @problem.severity error
 * @id py/http-header-injection
 * @tags security
 *       external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "options", "patch", "request", "stream", "Client", "AsyncClient"]).getACall() and
      sink = call.getArgByName("headers")
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential HTTP header injection from $@.", source.getNode(), "user input"
